"const fs = require('fs');
const path = require('path');

const brainPath = 'C:\\Users\\Administrador\\.gemini\\antigravity-ide\\brain';

function searchTranscripts() {
  if (!fs.existsSync(brainPath)) {
    console.log("Brain path does not exist:", brainPath);
    return;
  }

  const dirs = fs.readdirSync(brainPath);
  console.log(`Found ${dirs.length} items in brain path.`);

  for (const dirName of dirs) {
    const transcriptPath = path.join(brainPath, dirName, '.system_generated', 'logs', 'transcript.jsonl');
    if (fs.existsSync(transcriptPath)) {
      try {
        const content = fs.readFileSync(transcriptPath, 'utf8');
        const query = 'vaca';
        if (content.toLowerCase().includes(query)) {
          console.log(`FOUND '${query}' in conversation: ${dirName}`);
          // Print some surrounding lines
          const lines = content.split('\n');
          for (const line of lines) {
            if (line.toLowerCase().includes(query)) {
              try {
                const parsed = JSON.parse(line);
                console.log(`- Role: ${parsed.source}, Content: ${parsed.content ? parsed.content.substring(0, 300) : ''}`);
              } catch (e) {
                console.log(`- Row match (raw): ${line.substring(0, 300)}`);
              }
            }
          }
        }
      } catch (err) {
        console.error(`Error reading ${transcriptPath}:`, err.message);
      }
    }
  }
}

searchTranscripts();
