"const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

/**
 * Obtiene todos los propietarios/fincas con conteo de animales
 */
async function getPropietarios() {
  return await prisma.propietario.findMany({
    where: { activo: true },
    include: {
      _count: {
        select: { animales: true }
      }
    },
    orderBy: { nombre: 'asc' }
  });
}

/**
 * Registra un nuevo propietario/finca
 */
async function createPropietario(data) {
  return await prisma.propietario.create({
    data: {
      nombre: data.nombre,
      identificacion: data.identificacion,
      telefono: data.telefono,
      correo: data.correo,
      direccion: data.direccion
    }
  });
}

/**
 * Actualiza los datos de un propietario/finca
 */
async function updatePropietario(id, data) {
  return await prisma.propietario.update({
    where: { id: parseInt(id, 10) },
    data: {
      nombre: data.nombre,
      identificacion: data.identificacion,
      telefono: data.telefono,
      correo: data.correo,
      direccion: data.direccion,
      activo: data.activo !== undefined ? data.activo : undefined
    }
  });
}

