  } catch (error) {
    res.status(500).json({ error: 'Error al actualizar animal', message: error.message });
  }
}

async function getCatalogos(req, res) {
  try {
    const catalogs = await vetService.getCatalogos();
    res.json(catalogs);
  } catch (error) {
    res.status(500).json({ error: 'Error al obtener catálogos', message: error.message });
  }
}


