router.post('/propietarios', vetController.createPropietario);
router.put('/propietarios/:id', vetController.updatePropietario);

// Animales y Rebaños
router.get('/animales', vetController.getAnimales);
router.post('/animales', vetController.createAnimal);
router.put('/animales/:id', vetController.updateAnimal);

// Órdenes y Exámenes
router.get('/examenes', vetController.getExamenes);
