  const grayColor = '#757575';
  const tableHeaderBg = '#f1f8e9';

  // --- CABECERA ---
  doc.rect(50, 40, 512, 5).fill(primaryColor);

  doc.fillColor(primaryColor)
     .font('Helvetica-Bold')
     .fontSize(22)
     .text('CONTROLAB VET', 50, 60);

  doc.fillColor(textColor)
     .font('Helvetica')
     .fontSize(10)
     .text('Sistema de Información de Laboratorio Veterinario', 50, 85);

  // Fecha y Orden (Esquina superior derecha)
  doc.fillColor(secondaryColor)
     .font('Helvetica-Bold')
     .fontSize(10)
     .text(`CÓDIGO: ${examen.codigo_orden}`, 380, 60, { align: 'right', width: 180 });

  const fechaMuestraStr = new Date(examen.fecha_muestra).toLocaleDateString('es-ES', {
    day: '2-digit', month: '2-digit', year: 'numeric'
  });
  const fechaResultadoStr = examen.fecha_resultado ? new Date(examen.fecha_resultado).toLocaleDateString('es-ES', {
    day: '2-digit', month: '2-digit', year: 'numeric'
  }) : 'Pendiente';

  doc.font('Helvetica')
     .fontSize(9)
     .text(`Fecha Muestra: ${fechaMuestraStr}`, 380, 75, { align: 'right', width: 180 })
