"/**
 * Registra una nueva orden de examen veterinario (análisis de sangre)
 */
async function createExamen(data) {
  const count = await prisma.examenVeterinario.count();
  const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
  const codigo_orden = `VET-${dateStr}-${(count + 1).toString().padStart(3, '0')}`;

  const animal = await prisma.animal.findUnique({
    where: { id: parseInt(data.animal_id, 10) }
  });

  if (!animal) {
    throw new Error('Animal no encontrado');
  }

  return await prisma.$transaction(async (tx) => {
    const orden = await tx.examenVeterinario.create({
      data: {
        codigo_orden,
        animal_id: animal.id,
        propietario_id: animal.propietario_id,
        fecha_muestra: data.fecha_muestra ? new Date(data.fecha_muestra) : new Date(),
        estado: 'PENDIENTE',
        observaciones: data.observaciones
      }
    });

    if (data.parametro_ids && Array.isArray(data.parametro_ids) && data.parametro_ids.length > 0) {
      for (const pId of data.parametro_ids) {
        await tx.resultadoExamen.create({
          data: {
            examen_id: orden.id,
            parametro_id: parseInt(pId, 10),
            valor_numerico: null,
            valor_texto: null,
            fuera_rango: false
          }
        });
      }
    }

    return await tx.examenVeterinario.findUnique({
      where: { id: orden.id },
      include: {
        animal: true,
        propietario: true,
        resultados: {
          include: { parametro: true }
        }
      }
    });
  });
}"

