"const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function verify() {
  console.log('🔍 Checking Database Seeding Verification...');

  const speciesCount = await prisma.especie.count();
  console.log(`🐾 Total Especies: ${speciesCount}`);

  const species = await prisma.especie.findMany({ include: { razas: true } });
  species.forEach(esp => {
    console.log(`   - ${esp.nombre}: ${esp.razas.length} razas`);
    esp.razas.forEach(r => console.log(`     * Breed: ${r.nombre}`));
  });

  const paramsCount = await prisma.parametroExamen.count();
  console.log(`🧪 Total Parámetros: ${paramsCount}`);

  const refRangesCount = await prisma.valReferenciaExamen.count();
  console.log(`📋 Total Rangos de Referencia: ${refRangesCount}`);

  const breedSpecificCount = await prisma.valReferenciaExamen.count({
    where: { raza_id: { not: null } }
  });
  console.log(`🎯 Breed-specific Ranges: ${breedSpecificCount}`);

  const animalsCount = await prisma.animal.count();
  console.log(`🐑 Total Animales: ${animalsCount}`);

  const animals = await prisma.animal.findMany({
    include: { especie: true, raza: true }
  });
  animals.forEach(a => {
    console.log(`   - Animal ID: ${a.identificador} | Species: ${a.especie.nombre} | Breed: ${a.raza ? a.raza.nombre : 'General'}`);
  });

  console.log('✅ Verification finished!');
}

verify()
  .catch(console.error)
  .finally(() => prisma.$disconnect());
"

