"const PDFDocument = require('pdfkit');

/**
 * Genera el reporte clínico en PDF para un examen veterinario y lo escribe en el stream de respuesta.
 * Soporta dinámicamente 1 o 2 páginas de manera espaciosa y profesional sin encimarse.
 */
function generarExamenPDF(examen, stream) {
  const doc = new PDFDocument({
    size: 'LETTER',
    margins: { top: 30, bottom: 30, left: 40, right: 40 },
    autoPageBreak: false // Controlamos los saltos de página manualmente para un acabado perfecto
  });

  // Pipe the PDF document to the response stream
  doc.pipe(stream);

  // Colores del tema veterinario (Teal/Green profesional)
  const primaryColor = '#1b5e20';
  const secondaryColor = '#37474f';
  const accentColor = '#d32f2f'; // Rojo para valores alterados
  const textColor = '#212121';
  const grayColor = '#757575';
  const tableHeaderBg = '#f1f8e9';

  const rightX = 372;
  const fechaMuestraStr = new Date(examen.fecha_muestra).toLocaleDateString('es-ES', {
    day: '2-digit', month: '2-digit', year: 'numeric'
  });
  const fechaResultadoStr = examen.fecha_resultado ? new Date(examen.fecha_resultado).toLocaleDateString('es-ES', {
    day: '2-digit', month: '2-digit', year: 'numeric'
  }) : 'Pendiente';

  // Función para dibujar la cabecera en cualquier página
  function drawPageHeader(page) {
    // Barra verde superior
    doc.rect(40, 25, 532, 4).fill(primaryColor);

    doc.fillColor(primaryColor)
       .font('Helvetica-Bold')
       .fontSize(16)
       .text('CONTROLAB VET', 40, 35);

    doc.fillColor(textColor)
       .font('Helvetica')
       .fontSize(8)
