"const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function main() {
  const code = 'VET-20260623-007';
  const order = await prisma.examenVeterinario.findUnique({
    where: { codigo_orden: code },
    include: {
      animal: {
        include: {
          especie: true,
          raza: true
        }
      },
      resultados: {
        include: {
          parametro: true
        }
      }
    }
  });

  if (!order) {
    console.log(`❌ Order ${code} not found!`);
    // Let's print the last few orders to help debug
    const lastOrders = await prisma.examenVeterinario.findMany({
      take: 10,
      orderBy: { created_at: 'desc' },
      include: { animal: true }
    });
    console.log('\nLast 10 orders:');
    for (const o of lastOrders) {
      console.log(`- ${o.codigo_orden} | Animal: ${o.animal.identificador} (${o.animal.nombre}) | Estado: ${o.estado}`);
    }
  } else {
    console.log(`✅ Order found: ${order.codigo_orden}`);
    console.log(`   Animal ID: ${order.animal.identificador}`);
    console.log(`   Name: ${order.animal.nombre}`);
    console.log(`   Species: ${order.animal.especie.nombre}`);
    console.log(`   Breed: ${order.animal.raza ? order.animal.raza.nombre : 'No breed'}`);
    console.log(`   Sex: ${order.animal.sexo}`);
    console.log(`   Status: ${order.estado}`);
    console.log(`   Results count: ${order.resultados.length}`);
    for (const r of order.resultados) {
      console.log(`     - ${r.parametro.codigo}: ${r.valor_numerico} (Fuera rango: ${r.fuera_rango})`);
    }
  }
}

main()
  .catch(e => console.error(e))
  .finally(() => prisma.$disconnect());
"

