"const http = require('http');

function testEndpoint(url) {
  return new Promise((resolve, reject) => {
    http.get(url, (res) => {
      let data = '';
      res.on('data', chunk => { data += chunk; });
      res.on('end', () => {
        try {
          const parsed = JSON.parse(data);
          resolve({ status: res.statusCode, data: parsed });
        } catch (e) {
          resolve({ status: res.statusCode, data: data });
        }
      });
    }).on('error', reject);
  });
}

async function main() {
  console.log('Testing endpoint: /api/vet/examenes/evolucion');

  // Test 1: Search by order code
  console.log('\n--- Test 1: Search by order code (VET-20260622-002) ---');
  try {
    const res1 = await testEndpoint('http://localhost:5000/api/vet/examenes/evolucion?codigo_orden=VET-20260622-002');
    console.log(`Status: ${res1.status}`);
    if (res1.status === 200) {
      console.log('Success! Animal:', res1.data.animal.identificador);
      console.log('Species:', res1.data.animal.especie.nombre);
      console.log('Available Parameters in history:', Object.keys(res1.data.evolucion));
      if (res1.data.evolucion.HGB) {
        console.log('HGB history:', JSON.stringify(res1.data.evolucion.HGB, null, 2));
      }
    } else {
      console.log('Error data:', res1.data);
    }
  } catch (err) {
    console.error('Request failed:', err.message);
  }

  // Test 2: Search by animal identifier
  console.log('\n--- Test 2: Search by animal identifier (PERRO-01) ---');
  try {
    const res2 = await testEndpoint('http://localhost:5000/api/vet/examenes/evolucion?animal_identificador=PERRO-01');
    console.log(`Status: ${res2.status}`);
    if (res2.status === 200) {
      console.log('Success! Animal:', res2.data.animal.identificador);
      console.log('Owner:', res2.data.animal.propietario.nombre);
    } else {
      console.log('Error data:', res2.data);
    }
  } catch (err) {
    console.error('Request failed:', err.message);
  }
}

main();

