"const sql = require('mssql');
require('dotenv').config();

// Configuración centralizada de la base de datos
const dbConfig = {
  server: process.env.DB_SERVER || 'localhost',
  database: process.env.DB_DATABASE || 'ControlabIA',
  user: process.env.DB_USER || 'controlab_user',
  password: process.env.DB_PASSWORD || 'Delicia1.',
  port: parseInt(process.env.DB_PORT) || 1433,
  options: {
    encrypt: process.env.DB_ENCRYPT === 'true', // Usar true si estás en Azure
    trustServerCertificate: true, // true para desarrollo local
    enableArithAbort: true
  },
  pool: {
    max: 20,
    min: 0,
    idleTimeoutMillis: 30000
  }
};

// Singleton para el pool de conexiones
let poolPromise = null;

const getPool = () => {
  if (!poolPromise) {
    console.log('🔄 Inicializando Pool de Base de Datos...');
    poolPromise = new sql.ConnectionPool(dbConfig)
      .connect()
      .then(pool => {
        console.log('✅ Pool de base de datos conectado y listo.');
        return pool;
      })
      .catch(err => {
        console.error('❌ Error creando el pool de BD:', err);
        poolPromise = null; // Reiniciar en caso de error para reintentar
        throw err;
      });
  }
  return poolPromise;
};

// Función auxiliar para transacciones
const executeTransaction = async (transactionCallback) => {
  const pool = await getPool();
  const transaction = new sql.Transaction(pool);
  try {
    await transaction.begin();
    const result = await transactionCallback(transaction);
    await transaction.commit();
    return result;
  } catch (error) {
    await transaction.rollback();
    throw error;
  }
};

module.exports = {
  sql,
  getPool,
  executeTransaction
};"

