"const { PrismaClient: PrismaClientIA } = require('c:/controlab-ia/backend/node_modules/@prisma/client');
const { PrismaClient: PrismaClientVet } = require('c:/controlab-vet/backend/node_modules/@prisma/client');

const prismaIA = new PrismaClientIA();
const prismaVet = new PrismaClientVet();

async function main() {
  console.log('🔄 Fetching users from ControlabIA database...');
  const usersIA = await prismaIA.usuarios.findMany();
  console.log(`📋 Found ${usersIA.length} users in ControlabIA.`);

  console.log('🔄 Replicating users to ControlabVet database...');
  for (const u of usersIA) {
    const existing = await prismaVet.usuarios.findUnique({
      where: { usuario: u.usuario }
    });

    if (existing) {
      console.log(`⚠️ User ${u.usuario} already exists in ControlabVet, updating...`);
      await prismaVet.usuarios.update({
        where: { id: existing.id },
        data: {
          correo: u.correo,
          rol: u.rol,
          nombre_completo: u.nombre_completo,
          contrase_a: u.contrase_a, // mapped from contraseña
          activo: u.activo
        }
      });
    } else {
      console.log(`➕ Creating user ${u.usuario} in ControlabVet...`);
      await prismaVet.usuarios.create({
        data: {
          usuario: u.usuario,
          correo: u.correo,
          rol: u.rol,
          nombre_completo: u.nombre_completo,
          contrase_a: u.contrase_a, // mapped from contraseña
          activo: u.activo
        }
      });
    }
  }

  console.log('🎉 Done! User replication complete.');
}

main()
  .catch(console.error)
  .finally(async () => {
    await prismaIA.$disconnect();
    await prismaVet.$disconnect();
  });
"

