"const sql = require('mssql');
const { PrismaClient } = require('@prisma/client');
const fs = require('fs');
const path = require('path');

// Cargar .env
require('dotenv').config();

console.log('================================================================');
console.log('🩺 DIAGNÓSTICO DE CONEXIÓN A BASE DE DATOS CONTROLAB-VET LIS 🩺');
console.log('================================================================\n');

const dbUrl = process.env.DATABASE_URL;
console.log(`🔗 DATABASE_URL en .env: ${dbUrl ? dbUrl.replace(/:([^:@]+)@/, ':******@') : '❌ No definida'}\n`);

if (!dbUrl) {
  console.error('❌ Error: DATABASE_URL no está definida en el archivo backend/.env');
  process.exit(1);
}

// Parse Connection String
const parseDatabaseUrl = (url) => {
  try {
    const cleanUrl = url.replace('sqlserver://', '');
    const semicolonParts = cleanUrl.split(';');
    const hostPort = semicolonParts[0];
    const [server, portStr] = hostPort.split(':');
    const port = portStr ? parseInt(portStr, 10) : 1433;

    const params = {};
    for (let i = 1; i < semicolonParts.length; i++) {
      const part = semicolonParts[i];
      if (!part.trim()) continue;
      const [key, value] = part.split('=');
      if (key && value) {
        params[key.trim().toLowerCase()] = value.trim();
      }
    }

    return {
      server: server || 'localhost',
      database: params['database'] || 'ControlabVet',
      user: params['user'] || 'controlab_user',
      password: params['password'] || 'Delicia1.',
      port: port,
      encrypt: params['encrypt'] === 'true',
      trustServerCertificate: params['trustservercertificate'] === 'true'
    };
  } catch (err) {
    console.error('Error parsing DATABASE_URL:', err.message);
    return null;
  }
};

const config = parseDatabaseUrl(dbUrl);
if (!config) {
  console.error('❌ Error: Formato de DATABASE_URL inválido.');
  process.exit(1);
}

