"const { getPool } = require('../config/db');

async function runAlterTable() {
  try {
    const pool = await getPool();
    console.log('🔄 Checking if nombre column exists in database...');

    // Check if column already exists
    const checkRes = await pool.request().query(`
      SELECT COLUMN_NAME
      FROM INFORMATION_SCHEMA.COLUMNS
      WHERE TABLE_NAME = 'animales_vet' AND COLUMN_NAME = 'nombre'
    `);

    if (checkRes.recordset.length === 0) {
      console.log('➕ Column "nombre" not found. Adding it...');
      await pool.request().query(`
        ALTER TABLE animales_vet ADD nombre NVARCHAR(100) NULL;
      `);
      console.log('✅ Column "nombre" added successfully to animales_vet!');
    } else {
      console.log('ℹ️ Column "nombre" already exists in database.');
    }

    await pool.close();
  } catch (err) {
    console.error('❌ Error executing ALTER TABLE:', err);
  }
}

runAlterTable();
"

