"  const exportarExcelVet = () => {
    if (!reportData) return;
    try {
      const workbook = require('xlsx').utils.book_new();

      // Hoja de Resumen
      const resumenSheet = require('xlsx').utils.json_to_sheet([
        { 'Métrica': 'Total de Órdenes', 'Valor': reportData.resumenGeneral.totalOrdenes },
        { 'Métrica': 'Muestras Procesadas', 'Valor': reportData.resumenGeneral.totalProcesados },
        { 'Métrica': 'Ingresos Totales (USD)', 'Valor': `$${reportData.resumenGeneral.totalIngresos.toFixed(2)}` },
        { 'Métrica': 'Costo Estimado Reactivos (USD)', 'Valor': `$${reportData.resumenGeneral.totalCostos.toFixed(2)}` },
        { 'Métrica': 'Utilidad Neta (USD)', 'Valor': `$${reportData.resumenGeneral.totalUtilidad.toFixed(2)}` }
      ]);
      require('xlsx').utils.book_append_sheet(workbook, resumenSheet, 'Resumen Financiero');

      // Hoja de Especies
      const especiesSheet = require('xlsx').utils.json_to_sheet(reportData.especies);
      require('xlsx').utils.book_append_sheet(workbook, especiesSheet, 'Estadísticas por Especie');

      // Hoja Financiera
      const financieroSheet = require('xlsx').utils.json_to_sheet(reportData.financiero);
      require('xlsx').utils.book_append_sheet(workbook, financieroSheet, 'Rentabilidad');

      // Descargar
      const buffer = require('xlsx').write(workbook, { type: 'buffer', bookType: 'xlsx' });
      const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
      const downloadUrl = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = 'reporte_consolidado_vet.xlsx';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(downloadUrl);
    } catch (err) {
      console.error('Error al exportar Excel:', err);
      alert('Error al generar el archivo Excel');
    }
  };"

