  const payload = Buffer.from(text);
  const payloadLen = payload.length;

  let headerLen = 6; // 2 bytes header + 4 bytes mask key
  let maskStart = 2;
  if (payloadLen > 125) {
    headerLen += 2;
    maskStart = 4;
