  const testName = 'Hacienda El Oasis - Test ' + Date.now();
  const testReg = 'REG-OASIS-' + Math.floor(Math.random() * 10000);
  const testVet = 'Dr. Alejandro Gomez L.';

  // 1. Create a new propietario
  console.log('1. Creating owner/farm...');
  const createRes = await fetch('http://localhost:5000/api/vet/propietarios', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      nombre: testName,
      identificacion: 'J-99887766-5',
      telefono: '+58 424-9999999',
      correo: 'oasis@test.com',
      direccion: 'Sector El Jobo, Kilometro 5',
      registro_finca: testReg,
      nombre_veterinario: testVet
    })
  });

  if (!createRes.ok) {
    const errText = await createRes.text();
    throw new Error('Failed to create propietario: ' + errText);
  }

  const created = await createRes.json();
  console.log('   - Created Response:', created);

  if (created.registro_finca !== testReg) {
    throw new Error(`Expected registro_finca "${testReg}", got: ${created.registro_finca}`);
  }
  if (created.nombre_veterinario !== testVet) {
    throw new Error(`Expected nombre_veterinario "${testVet}", got: ${created.nombre_veterinario}`);
  }

  console.log('2. Fetching propietarios list to verify fields exist...');
  const getRes = await fetch('http://localhost:5000/api/vet/propietarios');
  const list = await getRes.json();
  const found = list.find(p => p.id === created.id);

  if (!found) {
    throw new Error('Propietario not found in list!');
  }

  console.log('   - Found in list:', found);
  if (found.registro_finca !== testReg) {
    throw new Error(`Expected saved registro_finca "${testReg}", got: ${found.registro_finca}`);
  }
  if (found.nombre_veterinario !== testVet) {
    throw new Error(`Expected saved nombre_veterinario "${testVet}", got: ${found.nombre_veterinario}`);
  }

