"const { spawn } = require('child_process');
const http = require('http');

const chromePath = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const remoteDebuggingPort = 9222;

console.log('🧪 Launching headless Chrome for IDGA Worksheet E2E test...');
const chrome = spawn(chromePath, [
  '--headless',
  '--disable-gpu',
  `--remote-debugging-port=${remoteDebuggingPort}`,
  '--no-sandbox',
  'http://localhost:3000/login'
]);

chrome.on('error', (err) => {
  console.error('❌ Failed to start Chrome:', err);
});

// Helper to encode a client-to-server WebSocket text frame (with masking)
const encodeFrame = (text) => {
  const payload = Buffer.from(text);
  const payloadLen = payload.length;

  let headerLen = 6; // 2 bytes header + 4 bytes mask key
  let maskStart = 2;
  if (payloadLen > 125) {
    headerLen += 2;
    maskStart = 4;
  }

  const buf = Buffer.alloc(headerLen + payloadLen);
  buf[0] = 0x81; // FIN + text frame

  if (payloadLen <= 125) {
    buf[1] = 0x80 | payloadLen;
  } else {
    buf[1] = 0x80 | 126;
    buf.writeUInt16BE(payloadLen, 2);
  }

  const maskKey = Buffer.from([0x12, 0x34, 0x56, 0x78]);
  maskKey.copy(buf, maskStart);

  const payloadStart = maskStart + 4;
  for (let i = 0; i < payloadLen; i++) {
    buf[payloadStart + i] = payload[i] ^ maskKey[i % 4];
  }
  return buf;
};

// Wait 4 seconds for Chrome to start
setTimeout(() => {
  console.log('🔗 Connecting to Chrome debugger...');
  http.get(`http://localhost:${remoteDebuggingPort}/json/list`, (res) => {
    let data = '';
    res.on('data', (chunk) => data += chunk);
    res.on('end', () => {
      try {
        const list = JSON.parse(data);
